<?php
require __DIR__.'/../admin.php';if(!admin_can('app_settings','update')){http_response_code(403);exit('Permission denied.');}$error='';$keys=array_values(array_filter(array_keys(sc_site_fields()),fn($key)=>str_starts_with($key,'footer_')));
if($_SERVER['REQUEST_METHOD']==='POST'){try{sc_admin_guard('app_settings','update',$_POST);sc_save_public_settings($_POST,$keys);header('Location: ./?saved=1',true,303);exit;}catch(Throwable $e){$error=$e instanceof mysqli_sql_exception?'Could not save the footer.':$e->getMessage();}}
admin_console_open('Website Footer');
?>
<p>Customize the footer shown across the public website. Contact details and social links are managed in <a href="../settings/">Settings</a>.</p><?php if(isset($_GET['saved'])): ?><p class="alert alert-success">Website footer saved.</p><?php endif; ?><?php if($error): ?><p class="alert alert-danger"><?= sc_e($error) ?></p><?php endif; ?><div class="card p-4"><form method="post"><?= sc_token() ?><?php foreach($keys as $key):$field=sc_site_fields()[$key]; ?><label class="d-block mb-3"><?= sc_e($field[0]) ?><?php if($key==='footer_description'): ?><textarea class="form-control" name="<?= $key ?>" maxlength="<?= $field[2] ?>" rows="4"><?= sc_e(sc_public_setting($key,$field[1])) ?></textarea><?php else: ?><input class="form-control" name="<?= $key ?>" maxlength="<?= $field[2] ?>" value="<?= sc_e(sc_public_setting($key,$field[1])) ?>"><?php endif; ?></label><?php endforeach; ?><button class="btn btn-primary">Save website footer</button><a class="btn btn-outline-secondary" href="<?= sc_url() ?>" target="_blank" rel="noopener">Preview website</a></form></div><?php admin_console_close(); ?>
